// Each row identifies the actual concept, a worked example and a specific error.
// Mathematical notation is restated in words in the beginner notes.
const t=(title,idea,example,pitfall,spec)=>({title,idea,example,pitfall,spec});
const w=input=>({kind:'words',input});
const d=(machine,input,extra={})=>({kind:'dfa',machine,input,...extra});
const re=(expression,input,kind='regex')=>({kind,expression,input});
const g=(grammar,input)=>({kind:'grammar',grammar,input});
const p=(input,extra={})=>({kind:'pda',input,...extra});
const close=(input,left='even-a',right='contains-b')=>({kind:'closure',input,left,right});
const dec=(model,problem)=>({kind:'decision',model,problem});
export const topics=[
t('What can a machine remember?','A computational model specifies its memory, permitted steps and acceptance rule. A finite automaton remembers only one of finitely many states.','A turnstile can remember locked or unlocked without remembering every earlier visitor.','Finite state does not mean finite input length: a state can be revisited.',d('even','101')),
t('Alphabets, words and the empty word','An alphabet is a finite nonempty set of symbols. A word is a finite sequence of symbols; ε is the unique word of length zero.','Over {a,b}, abba has four symbols, while ε has none.','The empty word ε is not the empty set ∅.',w('abba')),
t('Concatenating and reversing words','Concatenation writes one word after another without reordering its symbols. Lengths add, and ε changes neither operand.','For x=ab and y=ba, xy=abba; reversing xy gives reverse(y) followed by reverse(x).','Concatenation is generally not commutative: ab followed by a differs from a followed by ab.',w('aba')),
t('Prefixes, suffixes and subsequences','A prefix starts at the first symbol, a suffix ends at the last, a substring is contiguous and a subsequence may skip positions.','In abba, aba is a subsequence but not a contiguous substring; ab is a prefix.','A subsequence must preserve order even though it may omit symbols.',w('abba')),
t('Languages are sets of words','A language over Σ is any subset of Σ*. Membership asks whether a whole word is an element of that set.','{ε,a,ab} has three elements, not four symbols worth of elements.','A word and a set containing that word are different mathematical objects.',{kind:'language',input:'ab'}),
t('Union, intersection and difference of languages','Set operations combine whole-word membership: union means either, intersection means both, and difference means left but not right.','The word abb contains b but has an odd number of a symbols, so it is outside their intersection.','Union of languages does not concatenate their words.',close('abb')),
t('Language powers and Kleene star','L^n concatenates exactly n words from L; L^0={ε}. L* is the union of these powers for every nonnegative n.','If L={ab}, then L* contains ε, ab, abab and every further repetition.','∅*={ε}, because the zero-fold concatenation is still permitted.',re('(ab)*','abab')),
t('Work with words and sets separately','Count positions when measuring a word, but count distinct words when measuring a finite language. Repetition does not add a new set element.','The word aaa has length three; {a,a,aa} is just {a,aa} and has two elements.','A set does not keep duplicate copies merely because two constructions produce the same word.',{kind:'language',words:['','a','aa'],other:['a','aa'],input:'aaa'}),
t('Complement needs a fixed alphabet','The complement of L over Σ is Σ* minus L. A word changes membership, but the universe of valid words stays fixed.','Over {a,b}, the complement of {a^n b^n} contains ba, abb and a, but not ε.','Changing the alphabet changes the complement.',close('ba','anbn','all')),
t('Why finite memory is a restriction','A finite-state machine must summarize every consumed prefix using a fixed finite set of states, regardless of input length.','Remembering parity needs two states; remembering every exact unmatched a count needs unbounded memory.','An arbitrarily large fixed number of states is still finite.',{kind:'nerode',parameter:3}),
t('Read a finite-state diagram','A node represents remembered state; an arrow labeled with a symbol describes the next state after consuming that symbol.','In a parity machine, reading 1 switches between even and odd while reading 0 keeps the state.','Being in an accepting state halfway through a word does not finish the input.',d('even','1101')),
t('Runs and whole-input acceptance','A run starts at the designated start state and follows one transition per input symbol. Only its final state determines acceptance.','A parity run on 11 visits odd after one symbol and returns to even after two.','Acceptance is not the same as visiting an accepting state at some earlier point.',d('even','11')),
t('The five parts of a DFA','A DFA consists of states Q, input alphabet Σ, transition function δ, start state q₀ and accepting set F. δ maps every state-symbol pair to one state.','A two-state binary parity DFA has four defined state-symbol transitions.','A missing transition is not allowed in the total-DFA convention; add a rejecting sink if necessary.',d('even','010')),
t('Determinism means one next state','For each current state and next symbol, a DFA has exactly one next state. Its memory update cannot guess or inspect future input.','A prefix-ab recognizer commits to a rejecting sink if the first symbol is b.','A deterministic transition cannot choose among two destinations for the same state and symbol.',d('prefix','aba')),
t('Design a DFA for a required prefix','Give states meanings: no input yet, first a seen, prefix ab secured, and permanently wrong prefix.','The prefix-ab machine accepts abbaa but rejects aab, even though aab contains ab later.','Starts with ab and contains ab are different requirements.',d('prefix','abbaa')),
t('Suffix matching and length remainders','For a required suffix, remember the longest consumed suffix that is also a prefix of the target pattern; for modular length, remember the length remainder.','After abbab, a suffix-ab machine accepts because the final two symbols are ab.','A previous occurrence of a pattern does not guarantee that the word ends with it.',d('suffix','abbab',{pattern:'ab'})),
t('What regular means','A language is regular exactly when some finite automaton recognizes it. An infinite set of accepted words can still have a finite description.','All binary words with an even number of 1s form an infinite regular language.','Regular does not mean finite, and infinite does not mean nonregular.',d('even','1111')),
t('Binary value remainders','When a bit b is appended to a binary prefix of value v, the new value is 2v+b. Store only its remainder modulo m.','Binary 110 has value six and ends in remainder zero modulo three. The model treats ε as value zero.','Length modulo three is different from numeric value modulo three.',d('remainder','110',{modulus:3})),
t('Remember a discovered substring','A contains-pattern DFA tracks partial progress until the pattern is found, then stays in an accepting state for every remaining symbol.','A contains-ab machine accepts abaa even though that word does not end with ab.','Suffix matching must keep updating after a match; contains matching can keep a permanent found flag.',d('contains','abaa',{pattern:'ab'})),
t('Remember the second symbol from the end','A DFA can retain the last two symbols as a bounded window. Acceptance checks the older symbol in that window when the input ends.','For baa, the second-last symbol is a; for bab, it is also a. A one-symbol word fails.','A fixed distance from the right is bounded memory, despite the unknown total length.',d('second-last','baa')),
t('Recognize only the empty word','Make the start state accepting and send every first symbol to a rejecting sink. Then ε is accepted and every nonempty word is rejected.','The language {ε} needs a start distinction from the after-any-input sink over a nonempty alphabet.','An accepting start state does not make every word accepted.',d('empty-word','a')),
t('Extend a transition function to a word','The extended transition δ* starts with δ*(q,ε)=q and consumes a longer word one symbol at a time using δ.','For a prefix-ab DFA, δ*(start,ab) is the secured-prefix state.','δ takes one symbol; δ* takes an entire finite word, including ε.',d('prefix','abba')),
t('Complement a complete DFA','Keep the alphabet, start and transition graph and replace F with Q minus F. This swaps the result for every whole input.','Even parity and odd parity are complements over binary words; ε belongs only to even parity.','Flipping accepting states on an incomplete automaton without first adding a sink can give a wrong complement.',close('aab','even-a','all')),
t('A sink also changes acceptance under complement','A rejecting sink represents all prefixes that can no longer satisfy the original property. In the complement it becomes accepting.','A word beginning with b fails the prefix-ab property permanently but belongs to its complement.','Do not leave the sink rejecting when flipping every accepting state.',d('prefix','baba')),
t('Double complementation restores a language','For a fixed alphabet, complementing twice restores exactly the original set, including the empty word and all rejected words.','If a parity machine accepts 101, its first complement rejects it and the second accepts it.','Complement flips membership, not arrow direction or input order.',d('even','101')),
t('Product automata track two memories','A product state is a pair of component states. Both components consume the same symbol, and the accepting predicate expresses union or intersection.','Combine length divisible by three with suffix ab: a word must satisfy both tests for intersection.','A product does not feed one machine output into the other; both read the original input.',close('aabb')),
t('Why minimize a DFA?','Minimization merges states with identical future acceptance behavior after unreachable states are removed. It preserves the entire recognized language.','Two rejecting states may be different if appending a reaches acceptance from only one of them.','Equal current acceptance is necessary but not sufficient for equivalence.',{kind:'minimize',input:'1010'}),
t('Equivalent states agree on every suffix','States p and q are equivalent if every finite suffix z leads either both to acceptance or both to rejection. ε tests their current accepting flags.','An accepting state and a rejecting state are immediately distinguished by ε.','Testing just one or two suffixes cannot establish equivalence without a complete algorithm.',{kind:'minimize',input:'1100'}),
t('Remove unreachable states before counting','A state unreachable from the start cannot affect any word. Remove it before reporting the size of the minimal reachable machine.','A drawn graph may contain an unused accepting state without making its language nonempty.','A diagram node count alone is not a minimal-state lower bound.',{kind:'minimize',input:'1000'}),
t('Distinguish states by a witness suffix','One suffix that produces opposite acceptance outcomes proves that two states cannot be merged. A pair-graph search finds such witnesses.','If p is accepting and q is not, the witness is ε; otherwise a nonempty extension may distinguish them.','A witness must be appended unchanged to both prefixes.',{kind:'nerode',parameter:2}),
t('Partition refinement to a fixed point','Start by separating accepting from rejecting states. Repeatedly split a block when its states transition into different blocks on some symbol.','A stable block has one destination block for each symbol, so quotient transitions are well-defined.','Stop when no block changes, not after an arbitrary number of pictures.',{kind:'minimize',input:'0110'}),
t('Read the minimized quotient machine','Each final partition block becomes one state; transitions go between blocks and the start block contains the original start.','If all reachable states reject, every continuation rejects and the minimal complete machine is one rejecting state.','The all-rejecting machine still needs a start state.',{kind:'minimize',input:'0000'}),
t('Configurations contain state and unread input','For a one-way DFA, a configuration consists of its current state and the remaining suffix. A transition consumes exactly its first unread symbol.','After reading ab in abba, a prefix recognizer has secured the prefix and still has ba unread.','Two configurations with the same state may still have different unread suffixes.',d('prefix','abba')),
t('An equality language defeats finite memory','The language {a^n b^n : n≥0} requires arbitrarily many unmatched a symbols to be distinguished before the b block arrives.','The prefixes a² and a³ are distinguished by b²: aabb is in the language but aaabb is not.','The restriction is unbounded exact equality, not merely having two symbol types.',{kind:'nerode',parameter:2}),
t('An NFA keeps a set of possibilities','An NFA may have zero, one or several transitions for a symbol. A word is accepted if at least one complete run ends accepting.','A suffix-ab NFA can keep searching while another branch guesses that a is the start of the final ab.','All branches rejecting is required for rejection; one unsuccessful branch is not enough.',re('(a|b)*ab','aab','nfa')),
t('The NFA transition returns a set','For an NFA, δ(q,a) is a set of states. The empty set means that this branch has no continuation for that symbol.','After a transition, combine all destinations from the currently active states without keeping duplicate states.','Nondeterminism is a mathematical branching rule, not a random probability distribution.',re('a|ab','ab','nfa')),
t('Existential acceptance is not early acceptance','A successful NFA branch must consume every input symbol before ending in an accepting state. An accepting prefix is insufficient.','For the expression a|ab, the input abb is rejected despite the earlier acceptance possibilities.','A branch cannot silently discard extra input.',re('a|ab','abb','nfa')),
t('Guess a pattern start while scanning','A loop can keep a searching branch alive while another branch begins a candidate match. Overlapping candidate starts must remain possible.','The suffix-aa expression accepts aaa: a later guessed start provides the final two a symbols.','Committing to the first candidate can miss a later valid match.',re('(a|b)*aa','aaa','nfa')),
t('Combine alternative suffixes','Nondeterministic union provides separate possibilities for each allowed pattern; accepting either full pattern is sufficient.','The expression (a|b)*(abb|bab) accepts ababb because it ends in abb.','A shared prefix does not require discarding the other candidate until its branch fails.',re('(a|b)*(abb|bab)','ababb','nfa')),
t('Epsilon moves consume no input','An ε-transition changes state without consuming a symbol. Epsilon closure includes the starting states and everything reachable using only ε-moves.','For a|ε, the empty word is accepted through the ε alternative.','An ε-move is not an input symbol and does not advance the input position.',re('a|ε','','nfa')),
t('Epsilon closure terminates even with cycles','Track visited states when following ε-arrows. A cycle adds no new state after its members are already in the closure.','In (a*)*, repeated empty repetitions create ε-paths but do not require an infinite closure search.','Cycles in a finite graph do not create infinitely many distinct states.',re('(a*)*','aaa','nfa')),
t('Consume a word with epsilon closure','Start with the closure of the start state. For each symbol, take all matching edges and then take ε-closure again.','For (a|ε)b*, the word bbb uses the empty left alternative and three b repetitions.','Taking closure only at the beginning misses reachable states after later symbols.',re('(a|ε)b*','bbb','nfa')),
t('Separate input symbols from epsilon','A word supplied to an ε-NFA contains only alphabet symbols. The notation ε describes no consumed symbol, not a character to type into the word.','Leaving the word field blank supplies ε. Typing a letter not in the alphabet is an invalid experiment.','A transition labeled ε can be used between symbol-consuming steps.',re('a*b*','aab','nfa')),
t('Subset construction makes a DFA','A DFA subset state represents all ε-NFA states reachable after the same input prefix. Its next state is uniquely determined.','The empty subset is a rejecting sink when no NFA branch can continue.','Subset construction preserves acceptance, not the number of original states.',re('(a|b)*ab','baab','subset')),
t('Exponential bounds versus reachable subsets','An n-state NFA has at most 2^n state subsets. Only reachable subsets are needed, and many examples use far fewer than that upper bound.','A subset is accepting when it contains at least one original accepting state.','The bound 2^n is not the exact minimal DFA size for every n-state NFA.',re('ab|ba','aba','subset')),
t('Regular-expression operators','An expression denotes a language: union chooses either operand, concatenation joins words, and star permits any finite number of repetitions including zero.','In a|bb*, the right branch starts with b and then repeats b, while the left branch is just a.','Operator precedence is star first, then concatenation, then union unless parentheses override it.',re('a|bb*','bbb')),
t('Describe words containing a symbol','Over {a,b}, (a|b)*a(a|b)* denotes exactly the words containing at least one a. The parts around the chosen a may be empty.','The word bba has a witness a at its last position; bbb has none.','The expression does not require exactly one a.',re('(a|b)*a(a|b)*','bba')),
t('Parentheses change a language','Grouping determines which subexpression is repeated or concatenated. Compare a|ab with (a|a)b before applying algebraic rules.','a|ab contains a, whereas (a|a)b contains only ab.','Distributing a final b over union changes both alternatives, not just the one nearest it.',re('(a|a)b','a')),
t('Read an expression by its construction','Explain a complex expression by describing its outer operator and then each operand. A star creates a sequence of independently chosen operand words.','In (aa|b)*, each piece is either aa or b; baab is a valid concatenation of three pieces.','Counting a symbols alone is insufficient when the expression restricts how they can be grouped.',re('(aa|b)*','baab')),
t('Test boundary cases of expressions','Check ε, a shortest accepted word and a nearby rejected word. These expose mistaken mandatory versus optional repetitions.','a*b accepts b because a* may contribute zero a symbols, but it rejects ε because the final b is mandatory.','Star makes its own operand optional; it does not erase an adjacent required operand.',re('a*b','b')),
t('Overlapping regex descriptions','A word may have several decompositions under an expression while still being one member of the language. Ambiguity does not duplicate set elements.','In (a|aa)*, aa can be produced as a·a or as one aa piece.','Multiple decompositions do not make an expression invalid.',re('(a|aa)*','aa')),
t('Useful regular-expression identities','Union is idempotent and associative; concatenation distributes over union. ε is the concatenation identity and ∅ is its annihilator.','a(ε|b) and a|ab describe the same two words.','Union is commutative, but concatenation generally is not.',re('a(ε|b)','ab')),
t('Nested stars and empty-language cases','Zero repetitions always contribute ε, and repeating an already starred language adds no new words: (L*)*=L*.','∅* contains ε only; (a*)* describes exactly a*.','∅ and ε cannot be substituted for each other in an expression.',re('(a*)*','aaaa')),
t('Expressions and finite automata agree','Regular expressions, ε-NFAs and DFAs describe exactly the regular languages, with effective conversions between representations.','Convert (ab)* into an ε-NFA, then track its active states on abab.','Equivalent expressive power does not imply equal diagram size.',re('(ab)*','abab','nfa')),
t('Build an NFA compositionally','Thompson construction makes fragments for symbols and joins them with ε-edges for union, concatenation and star. Each fragment has entry and exit states.','For (a|b)*ab, build the union, close it under repetition, then attach mandatory a and b fragments.','The star back edge must allow zero repetitions as well as more repetitions.',re('(a|b)*ab','bab','nfa')),
t('State elimination preserves all path labels','To remove state k, add R_ik(R_kk)*R_kj to each surviving path label R_ij. The star accounts for any number of loops at k.','If the path into k reads a, its loop reads b and its exit reads a, that contribution is ab*a.','Removing a node without adding its through-paths loses accepted words.',re('ab*a','abba')),
t('Choose an elimination order without changing language','Different state-elimination orders can yield different-looking expressions. Equivalence concerns their languages, not textual equality.','ab*|ab*b denotes the same language as ab*, because the second alternative adds no new word.','A longer resulting expression need not describe a larger language.',re('ab*|ab*b','abbb')),
t('Unary regular languages remember lengths','With a one-symbol alphabet, a finite automaton eventually cycles, so accepted lengths are eventually periodic. A finite prefix may behave differently.','(aa)* accepts precisely even lengths over {a}; the only information needed is length modulo two.','Not every unary language is regular: square lengths are not eventually periodic.',{...re('(aa)*','aaaa'),alphabet:['a']} ),
t('Describe finite beginnings and repeating tails','Separate a finite exceptional prefix of lengths from a repeating tail. Expressions can combine fixed words with a starred cycle.','a|aa(aaa)* accepts length one and lengths 2,5,8,… over the unary alphabet {a}.','A cycle begins after a specified entry path; do not assume every accepted length starts at zero.',{...re('a|aa(aaa)*','aaaaa'),alphabet:['a']} ),
t('The regular pumping lemma','If L is regular, some p works for every word w in L of length at least p: w=xyz with |xy|≤p, |y|>0 and xy^iz in L for every i≥0.','For a^p b^p, every legal y lies in the a block. Pumping down removes a symbols but no b symbols.','The opponent chooses the decomposition; showing failure for one convenient split is insufficient.',{kind:'pumping',parameter:4,split:1,power:0}),
t('Respect pumping quantifiers','To refute regularity, handle an arbitrary proposed pumping length and every legal decomposition of your chosen witness. Then choose a repetition count.','In a^p b^p, let y=a^k for any 1≤k≤p. With i=0, a^(p−k)b^p violates equality.','You may choose the witness and pumping exponent, but not force the opponent to choose your favorite legal split.',{kind:'pumping',parameter:5,split:2,power:0}),
t('Pump up as well as down','The lemma requires every nonnegative exponent to keep the word in the language, so either deleting or duplicating the repeatable piece may yield a contradiction.','Duplicating a nonempty a-only y in a^p b^p produces more a symbols than b symbols.','The lemma does not restrict the exponent to values greater than one; zero is also legal.',{kind:'pumping',parameter:3,split:2,power:2}),
t('Separate a demonstration from a pumping proof','A slider illustrates one pumping length and split. The proof must also explain why the same argument works for arbitrary p and every allowed y.','The first p positions of a^p b^p are all a, forcing all legal repeated pieces to contain a only.','Trying many finite witnesses is evidence, not a proof about all lengths.',{kind:'pumping',parameter:6,split:3,power:0}),
t('Pumping cannot certify regularity','The pumping condition is necessary for regularity, but satisfying it is not a general regularity test. Construct an automaton or expression to prove regularity.','A DFA tracking length modulo three directly proves that multiples-of-three lengths are regular.','Failure to find a pumping contradiction does not prove that a language is regular.',d('length','aababb',{modulus:3})),
t('Myhill–Nerode looks at future behavior','Two prefixes are equivalent for L when every shared appended suffix gives the same membership outcome. A DFA state must identify only equivalent prefixes.','For a^n b^n, a² and a³ are separated by b².','Comparing the prefixes themselves is not enough; compare all future extensions.',{kind:'nerode',parameter:2}),
t('Choose one distinguishing suffix for both strings','To distinguish x and y, find a single z such that exactly one of xz and yz belongs to L. The same z must be used on both.','For x=a³ and y=a⁴, z=b³ makes only xz balanced.','Different suffixes on the two prefixes do not meet the distinguishing condition.',{kind:'nerode',parameter:3}),
t('Build infinitely many distinguishable prefixes','An infinite family of pairwise-distinguishable prefixes forces infinitely many distinct memory states. This proves nonregularity.','For any unequal i,j, append b^i to a^i and a^j; exactly the first extension has equal blocks.','One distinguished pair proves a two-state lower bound, not an infinite lower bound.',{kind:'nerode',parameter:4}),
t('The Myhill–Nerode theorem','A language is regular exactly when its future-equivalence relation has finitely many classes; the number of classes equals the size of its minimal complete DFA.','Even and odd counts of 1 produce two distinct future behaviors for binary parity.','A lower bound becomes an exact answer only after a matching construction or finite-class proof.',d('even','1001')),
t('Use a suffix to check a claimed merge','If someone merges two memories, test a continuation that should make their outcomes differ. A single valid witness invalidates the merge.','Prefixes a and aa cannot be merged for equal-block membership, because suffix b accepts only the first.','Merging states that agree on the current word may break a later continuation.',{kind:'nerode',parameter:1}),
t('Count minimal states using upper and lower bounds','Build a DFA for an upper bound and exhibit that many distinguishable reachable memories for a lower bound. Matching bounds establish minimality.','For length divisible by three, three remainder states suffice; suffixes of suitable lengths distinguish all three.','Counting states in one nonminimal construction gives only an upper bound.',d('length','aababa',{modulus:3})),
t('Reachable residues are distinct future classes','For length modulo m, every residue is reachable. A suffix completing one residue to zero will not complete a different residue.','For m=4, append one symbol to residue three and residue two: only residue three reaches zero.','A modular state count requires reachable and pairwise-distinguishable residues, not just m labels.',d('length','aab',{modulus:4})),
t('Context-free grammars generate words','A CFG has nonterminals, terminals, productions and a start symbol. Replace one nonterminal at a time; a completed word contains terminals only.','S→aSb|ε generates ε, ab, aabb and so on by nesting matching outer symbols.','A sentential form containing S is not yet a terminal word.',g('S -> aSb | ε','aabb')),
t('Grammar recursion can nest or concatenate','A production controls how smaller generated pieces fit together. S→aSb nests matching symbols, while S→SS concatenates independently generated pieces.','S→aSb|SS|ε generates abab through concatenation as well as aabb through nesting.','Adding S→SS changes equal blocks into a larger balanced family; do not ignore the new alternative.',g('S -> aSb | SS | ε','abab')),
t('Regular grammars keep one-directional nonterminals','A right-linear grammar uses terminal strings followed by at most one nonterminal. Consistent right-linearity gives a regular language.','S→aS|bA and A→bA|ε generate a*b+.','A general CFG rule such as S→aSb is not right-linear.',g('S -> aS | bA; A -> bA | ε','aabbb')),
t('Convert an automaton to a right-linear grammar','Create one nonterminal for each state, a production P→aQ for each transition, and P→ε for every accepting state.','The grammar S→aA|bS, A→aA|bB, B→aB|bB|ε generates words containing ab.','Only accepting states receive the empty-production option.',g('S -> aA | bS; A -> aA | bB; B -> aB | bB | ε','baaba')),
t('Convert a right-linear grammar to an NFA','Treat nonterminals as states. A terminal-leading production creates a matching edge; a terminal-only production finishes at an accepting state.','S→aS|bA with A→ε accepts zero or more a symbols followed by one b.','Grammar nondeterminism can produce several same-symbol transitions, so a DFA is not always the direct result.',g('S -> aS | bA; A -> ε','aaab')),
t('A pushdown automaton adds a stack','A PDA combines finite control with a last-in-first-out stack. A transition inspects the top, may replace it and may consume an input symbol.','For a^n b^n, push while reading a and pop once per b, while enforcing a-before-b order.','A stack is not a queue: the newest unmatched item is removed first.',p('aabb')),
t('Read stack configurations','A PDA configuration includes its control state, unread input and complete stack. State changes and stack updates together determine the next configuration.','After aa in aaabbb, two unmatched a symbols must still be remembered, plus the bottom marker.','The bottom marker is not an unmatched a and should not count toward the equality test.',p('aaabbb')),
t('Both symbol order and stack balance matter','An equal final count alone does not recognize a^n b^n. The control must reject a symbols after the first b has begun the closing phase.','abab has equal a and b counts but violates the required block order.','Never accept merely because a signed counter returns to zero.',p('abab')),
t('Recognize equal ordered blocks','For a^n b^n, every a stores one obligation and every b discharges one. Accept only after all input is read with no obligation left.','aaabbb leaves only the bottom marker; aabbb has one extra b and must fail.','An empty stack before all input is consumed does not finish acceptance.',p('aaabbb')),
t('Shift equality by one symbol','To recognize a^n b^(n+1), reserve one additional b beyond the n matching pairs. The finite control can remember this fixed extra requirement.','For n=2, aabbb is valid while aabb is missing the required extra b.','A constant offset does not require a second unbounded memory structure.',p('aabbb',{offset:1})),
t('Compare unequal block counts','A stack can represent the signed difference between the a and b block counts, provided the control still enforces block order.','aaab belongs to {a^n b^m:n>m}; abbb does not.','Having more symbols in total does not say which block is larger.',p('aaab',{relation:'greater'})),
t('Recognize a larger second block','Switch from cancelling stored a obligations to storing surplus b symbols when the bottom is reached. Then inspect the sign after all input.','abbb has a second block longer than its first, so n<m.','Rejecting the first unmatched b would incorrectly lose valid n<m words.',p('abbb',{relation:'less'})),
t('Exclude equality while retaining ordered blocks','To recognize ordered blocks with unequal counts, reject exactly the zero-balance case after validating the a*b* shape.','aab is unequal and ordered; aba is unequal but not ordered and still fails.','The complement of equality over all words includes wrong-order words, but the unequal-block language does not.',p('aab',{relation:'unequal'})),
t('Two b symbols per a symbol','Push two obligations for each a and remove one for each b. Finite control still checks that all a symbols precede all b symbols.','aabbbb has four b symbols for two a symbols and satisfies b-count = 2×a-count.','Pushing once and popping twice per b would reverse the intended ratio.',p('aabbbb',{aWeight:2})),
t('Two a symbols per b symbol','Push one obligation for each a and discharge two per b, using fixed intermediate control steps if a formal PDA pops only one symbol at a time.','aaaabb has four a symbols and two b symbols, satisfying a-count = 2×b-count.','A fixed-size multi-pop in a teaching trace abbreviates finitely many ordinary PDA transitions.',p('aaaabb',{bWeight:2})),
t('Guess the midpoint of an even palindrome','An NPDA for wwᴿ guesses when to stop pushing, then matches the remaining symbols against stack pops. One correctly guessed full run is enough.','abba has midpoint after ab and matches ba against stack top b then a.','An unmarked midpoint is not visible to deterministic one-way control.',{kind:'palindrome',input:'abba'}),
t('Final-state and empty-stack acceptance','For NPDAs, final-state and empty-stack acceptance define the same language family through constructions. In either convention the entire input must be consumed.','A machine reaching its final state with unread b symbols has not accepted that whole word.','The NPDA equivalence does not justify identical acceptance-mode claims for every DPDA.',p('aab')),
t('Trace an unexpected extra symbol','When an obligation-matching stack reaches its bottom, a further closing symbol must be handled according to the exact language definition.','aabbb fails equal-block recognition because one b has no matching stored a.','An accepting prefix aabb cannot hide the final unread b.',p('aabbb')),
t('Separate unordered balance from ordered blocks','Equal counts do not enforce contiguity. A language of arbitrary balanced words needs a different transition discipline from the a*b* language.','abba has equal counts, but its final a violates a*b* and is rejected by this block recognizer.','A model for a^n b^n is not a model for every word with equally many a and b symbols.',p('abba')),
t('Why empty-stack conventions need care','An end marker can signal that input is finished and permit final cleanup. Without an end marker, deterministic empty-stack languages obey stronger restrictions.','If an empty-stack DPDA accepts a word, it cannot continue from that empty stack to accept a proper extension under the usual convention.','Do not equate deterministic final-state and deterministic empty-stack power without stating the input-end convention.',p('ab')),
t('Repair an acceptance-condition mistake','A correct trace must satisfy the language definition, input exhaustion and stated acceptance convention simultaneously. A partially correct run is not enough.','For aabb followed by another b, emptying the obligations at aabb cannot certify the full word.','Checking only stack height can miss unread symbols and wrong control phases.',p('aabbb')),
t('Use a midpoint marker to remove guessing','For w#wᴿ, the # symbol tells a DPDA exactly when to switch from push to match. Reject any second marker or unmatched remainder.','ab#ba accepts; ab#ab rejects when the first compared symbol differs.','The marker is a real input symbol and must occur exactly once.',{kind:'palindrome',input:'ab#ba',marker:true}),
t('Determinism forbids epsilon/input conflicts','For a DPDA, a state and stack-top pair cannot simultaneously offer an ε-transition and an input-consuming alternative. The next move must be unambiguous.','A marker-driven palindrome recognizer switches phase on # rather than guessing the boundary with ε.','Having at most one move per individual label is insufficient if an ε alternative can compete.',{kind:'palindrome',input:'ba#ab',marker:true}),
t('Deterministic CFLs form a proper subclass','Every DCFL is context-free, but not every CFL has a deterministic pushdown recognizer. Visible structural boundaries can make deterministic recognition possible.','Marked mirror words have an explicit boundary; unmarked even palindromes require nondeterminism in the one-way PDA model.','A nondeterministic construction alone does not prove that no deterministic construction exists.',{kind:'palindrome',input:'baab'}),
t('Finite memory versus unbounded equality','Identify what the machine must remember, then decide whether it is a bounded category or an arbitrary exact count.','Suffix ab uses three prefix-match memories; equality a^n b^n separates infinitely many a-prefixes.','Words with two separate blocks are not automatically nonregular.',{kind:'nerode',parameter:5}),
t('A modular condition does not compare exact counts','A fixed modulus has finitely many residues even when counts grow without bound. Exact equality of independent unbounded blocks is different.','Lengths congruent to zero modulo five need only five residue states.','A large fixed modulus is not an unbounded counter.',d('length','aababb',{modulus:5})),
t('Use overlapping patterns carefully','Two pattern occurrences may overlap. A suffix-prefix construction preserves the longest useful overlap instead of resetting blindly after a partial failure.','The suffix aba occurs at the end of ababa even though earlier occurrences overlap.','A failed candidate does not mean that every useful prefix has been lost.',d('suffix','ababa',{pattern:'aba'})),
t('Classify by the least sufficient model','A regular construction proves a language is also CFL and decidable, but the smallest sufficient model gives the strongest classification.','The marked mirror language is handled by a stack; bounded suffix tests need only finite state.','A Turing machine implementation does not imply that the language needs Turing-machine power.',{kind:'hierarchy'}),
t('Reversal differs from copying in the same order','A single stack naturally reverses the pushed prefix. Comparing an arbitrary copy in forward order is a different requirement.','For w=ab, w#wᴿ is ab#ba, whereas w#w is ab#ab.','A palindrome stack cannot be reused unchanged to recognize arbitrary same-order duplication.',{kind:'palindrome',input:'ab#ab',marker:true}),
t('Regular union and intersection use products','Track the two DFA states together and choose the final-pair predicate: OR for union and AND for intersection. Finite times finite remains finite.','A word with even a-count and at least one b satisfies the intersection of those two regular languages.','Closure concerns every pair in the family, not just one successful membership example.',close('aabb')),
t('Regular complement and difference stay regular','Complete-DFA complementation and the product construction give effective recognizers for difference and symmetric difference. The universe stays fixed.','L₁−L₂ keeps even-a words containing no b when L₂ is the contains-b language.','Difference is directional: L₁−L₂ need not equal L₂−L₁.',close('aaaa')),
t('CFL and DCFL closure are different','CFLs are closed under union, concatenation and star but not general intersection or complement. DCFLs are closed under complement but not general union.','Intersecting any CFL with a regular language stays CFL by running finite control alongside its stack.','Do not transfer a closure fact from CFLs to DCFLs solely because one class contains the other.',{kind:'hierarchy'}),
t('Regular filters preserve deterministic stack behavior','A DPDA can carry a DFA state alongside its own finite control. This recognizes intersection with a regular filter without adding nondeterministic choices.','An ordered-block filter can be checked in finite control while a stack compares the block counts.','DCFLs are not closed under arbitrary DCFL intersection.',p('aaabbb')),
t('Nonregular languages do not inherit regular closure','A family consisting of all nonregular languages is not closed under union or intersection. Combining two hard languages can cancel the difficulty.','If L is nonregular then its complement is nonregular, but their union is Σ* and their intersection is ∅, both regular.','A union containing a nonregular operand is not necessarily nonregular.',close('aabb','anbn','not-anbn')),
t('The Chomsky hierarchy compares memory resources','Regular, context-free and context-sensitive languages fit strictly inside Turing-recognizable languages. Decidable languages sit between context-sensitive and recognizable.','a^n b^n is context-free but not regular; arbitrary TM recognition may fail to halt on nonmembers.','Context-sensitive does not mean every decidable language.',{kind:'hierarchy'}),
t('Finite closure does not imply infinite closure','Regular languages are closed under finite union, but an infinite union of singleton regular languages can be any chosen language. Arbitrary subsets need not be regular either.','The union over all n≥0 of {a^n b^n} is nonregular even though every singleton is regular.','A theorem about two operands cannot automatically be iterated infinitely many times.',{kind:'nerode',parameter:6}),
t('Finite languages are always regular','A finite trie plus a rejecting sink recognizes any finite language. Finite union, intersection and concatenation remain finite; star may produce an infinite regular language.','{ab} is finite, while {ab}* is infinite and still regular.','The family of finite languages is not closed under star or complement over a nonempty alphabet.',re('(ab)*','ababab')),
t('DCFLs need not survive concatenation or star','A deterministic stack machine may rely on a visible phase boundary. Concatenating languages or iterating a language can hide that boundary and require choices.','A construction proving CFL closure may guess a split; that guess is not automatically available to a DPDA.','Failure of one greedy split algorithm is not by itself a proof of nonclosure.',{kind:'palindrome',input:'aabbaa'}),
t('Complement preserves the minimal complete DFA size','If a complete DFA is minimal, flipping its accepting flags preserves distinguishability of every pair: their yes/no outcomes are both reversed.','A three-state remainder-language DFA and its complement both need three states over the same alphabet.','This equal-size claim uses complete minimal DFAs and a fixed alphabet.',d('length','aabb',{modulus:3})),
t('A Turing machine can rewrite its tape','A TM has finite control, a read/write tape and a head that moves left or right. Each step reads one cell, writes one symbol and changes state.','A unary incrementer scans 111, writes one more 1 at the first blank and halts with 1111.','A tape cell and a finite-control state serve different roles.',{kind:'tm',machine:'unary',input:'111'}),
t('Mark and match on a tape','To decide a^n b^n, repeatedly mark the next a, find a matching unmarked b and return left. Finally verify that no unmatched symbol remains.','On aabb, X and Y mark completed pairs while the head makes several passes.','A multi-pass tape can revisit input; a one-way finite automaton cannot.',{kind:'tm',input:'aabb'}),
t('Tape alphabets include working symbols','The input alphabet excludes blank, while the tape alphabet includes blank and any markers written during computation. A transition is determined by state and scanned tape symbol.','The equal-block TM reads a and b but may write X and Y to mark progress.','Working markers need not be valid symbols in the user-supplied input.',{kind:'tm',input:'aaabbb'}),
t('An open mathematical claim is not a halting oracle','A program searching for a counterexample may run for an arbitrarily long time. Without a proof, its observed runtime cannot settle a universal mathematical claim.','A bounded simulation can report that no halt was seen in 40 steps; it cannot conclude that the machine never halts.','Unknown, disproved and proven are different statuses. A long wait is not a mathematical proof.',{kind:'tm',machine:'loop',input:'01',limit:40}),
t('Binary increment needs carry propagation','Scan to the right end, move left through trailing 1s while writing 0s, then replace the first 0 or left blank by 1 and halt.','Incrementing 111 yields 1000; incrementing 101 yields 110.','Adding one is not the same as appending the bit 1.',{kind:'tm',machine:'binary',input:'111'}),
t('Nonhalting differs from explicit rejection','A recognizer may reject a nonmember or run forever. A finite teaching run reaching its step budget has an unknown halting outcome, not a rejection.','The example right-moving loop reaches the display limit without entering a halting state.','A simulator timeout cannot safely be labeled rejects.',{kind:'tm',machine:'loop',input:'010',limit:30}),
t('A decider halts on every input','A decider must accept members, reject nonmembers and halt on both. A recognizer has the acceptance guarantee but may not halt on nonmembers.','The mark-and-match equal-block machine ends on both aabb and aabbb.','Halting on the tested examples does not prove total halting for an arbitrary machine.',{kind:'tm',input:'aabbb'}),
t('Check the full machine configuration','A TM configuration includes control state, head position and all relevant tape contents. Repeating the exact configuration in a deterministic run forces repeated future behavior.','Revisiting the same control state with changed tape does not establish an infinite loop.','State repetition alone is not configuration repetition.',{kind:'tm',machine:'binary',input:'1011'}),
t('Dovetail simulations fairly','Run each unfinished branch for a bounded turn and repeat. A branch that eventually accepts gets enough turns even if an earlier branch runs forever.','A three-branch schedule advances all three instead of waiting forever for branch one.','Running recognizers sequentially can get stuck before reaching a successful branch.',{kind:'dovetail',parameter:4}),
t('Encode machines as finite words','A machine description is finite and can be encoded as a word. An effective unambiguous encoding lets another algorithm inspect or simulate the described machine.','A finite list of states and transitions can be serialized using delimiters and symbol codes.','A code is a representation of a machine, not the machine running on its own.',dec('DFA','membership')),
t('Decision problems are languages of encodings','A yes/no problem becomes the set of valid encodings whose answer is yes. State exactly what the input describes before discussing decidability.','DFA membership takes both a DFA description and a word, not just a bare word.','The complexity of a represented object and the length of its encoding are distinct quantities.',dec('DFA','emptiness')),
t('Syntactic properties can be directly inspected','A question about a finite written description may be decidable by parsing it, even when behavior questions about the represented program are undecidable.','Counting declared states terminates; deciding whether arbitrary code accepts some input is a different task.','Rice’s theorem concerns recognized languages, not every property of a machine description.',{kind:'reduction',reduction:'rice'}),
t('Membership and universality use different quantifiers','Membership fixes one input word. Universality asks about every word in the alphabet universe. Changing the representation can change decidability of these problems.','For a DFA, universality can be decided by complementing it and testing for reachable accepting states.','An infinite set of candidate words does not itself make a decision problem undecidable.',dec('DFA','universality')),
t('Recognizing yes instances may not decide no instances','Simulating a TM on a fixed word recognizes acceptance if it occurs. If the simulation never accepts, waiting does not produce a guaranteed no answer.','The language of accepting machine-word encodings is recognizable but not decidable.','Not observing acceptance within a chosen time budget is not a no certificate.',dec('TM','membership')),
t('Graph search decides regular-language questions','Finite-state structure supports terminating algorithms: membership follows a run, emptiness searches reachability and universality checks complemented reachability.','An accepting state unreachable from the start does not make a DFA language nonempty.','Testing a sample of short strings cannot replace graph reachability.',dec('DFA','emptiness')),
t('Decide DFA equivalence with symmetric difference','Build a product accepting exactly when one component accepts and the other rejects. The original DFAs are equivalent exactly when that language is empty.','A reachable disagreeing pair gives a concrete counterexample word.','Equal state counts do not imply equivalent languages.',dec('DFA','equivalence')),
t('Remove nongenerating and unreachable grammar parts','First compute which nonterminals can derive a terminal word. Remove the rest, then find what remains reachable from the start.','In S→AB|a, A→a and B→B, the AB alternative can never finish; A then becomes unreachable in the useful grammar.','Reachability in the original grammar alone can retain symbols made unreachable by the generating-symbol removal.',{kind:'grammar-properties',grammar:'S -> AB | a; A -> a; B -> B; C -> b'}),
t('Nullable variables and unit chains','A nullable nonterminal can derive ε. Removing ε-productions requires adding alternatives for omitted nullable occurrences; unit productions require following nonterminal-to-nonterminal chains.','If A is nullable in S→aAb, include S→ab when eliminating A→ε, while preserving ε membership through the start convention.','Deleting empty and unit rules without adding their consequences changes the language.',{kind:'grammar-properties',grammar:'S -> aAb | C; A -> aA | ε; C -> b'}),
t('CNF and GNF production shapes','CNF uses A→BC or A→a; GNF uses A→aα with α a string of nonterminals. A stated start-only ε exception handles the empty word.','S→AB, A→a and B→b are in CNF. S→aB is GNF-shaped but not CNF-shaped.','A structural normal-form check is not an algorithm for testing arbitrary grammar equivalence.',{kind:'normal-form',form:'CNF',grammar:'S -> AB; A -> a; B -> b'}),
t('Some CFG questions are decidable and others are not','CFG membership and emptiness are decidable, while equivalence and universality for arbitrary CFGs are undecidable. Always keep the representation fixed.','A chart parser can terminate on a fixed finite word even when no general equivalence algorithm exists for two CFGs.','Decidable for DFAs does not imply decidable for CFGs.',dec('CFG','membership')),
t('A universal simulator does not decide acceptance','A universal TM interprets an encoded machine and simulates it on an encoded input. If the simulated machine runs forever, so may the simulator.','Providing a general simulator solves execution, not the requirement to answer yes or no and always halt.','Universal means able to simulate any encoded machine, not able to predict every future outcome.',dec('TM','membership')),
t('The halting problem has no total general decider','There is no algorithm that correctly decides for every encoded TM and input whether that computation eventually halts. Halting remains recognizable by simulation.','A self-reference contradiction defeats a hypothetical total halting predictor. A bounded run only reports what happened within its bound.','Undecidability does not mean that every individual machine has an unknown halting behavior.',dec('TM','halting')),
t('Rice’s theorem concerns semantic language properties','Every nontrivial property of the language recognized by an arbitrary TM is undecidable. Nontrivial means true of at least one recognizable language and false of another.','Being empty is a property of the recognized language. Having exactly five states is a property of its description.','The theorem does not apply to trivial properties or purely syntactic machine properties.',{kind:'reduction',reduction:'rice'}),
t('Check nontriviality with two witness languages','Before applying Rice’s theorem, show that some recognizable language has the property and another does not. The property must depend only on the language.','For nonemptiness, ∅ is a no witness and {ε} is a yes witness.','A property true of all recognizable languages is trivial and cannot yield a Rice contradiction.',{kind:'reduction',reduction:'nonempty'}),
t('Language equivalence does not preserve machine syntax','Two machines may recognize exactly the same language while having different state counts, unreachable code or runtimes. Those facts are not language properties.','Adding an unreachable state preserves L(M) but changes the written number of states.','An undecidability conclusion may still be true for other reasons, but Rice alone requires extensional language dependence.',{kind:'reduction',reduction:'rice'}),
t('Bounded execution questions can be decidable','For a fixed finite step bound, simulate only that many steps and inspect the result. This does not solve an unbounded behavior question.','Does this machine halt within 30 steps? is decidable by a 30-step simulation; does it eventually halt? is not generally decidable.','A finite time bound must be part of the stated problem, not silently introduced to replace eventual halting.',{kind:'tm',machine:'loop',input:'10',limit:30}),
t('Reduction direction carries an impossibility proof','To prove a target problem undecidable, transform instances of a known undecidable source into target instances, preserving yes and no outcomes.','From M,w construct N that accepts every y exactly when M accepts w. Deciding whether L(N) is nonempty would decide acceptance of M,w.','Reducing the target to an undecidable source does not prove the target undecidable.',{kind:'reduction',reduction:'nonempty'}),
t('Recognizable and decidable closure','Decidable languages are closed under complement. Recognizable languages are closed under union and intersection using fair simulation, but not general complement.','If both L and its complement are recognizable, dovetail their recognizers; one must accept, giving a decider for L.','Here recognizable is not the same meaning as regular-expression notation.',{kind:'dovetail',parameter:5}),
t('Countability is about an exhaustive indexing','A set is countable when it is finite or can be listed using natural-number positions. An infinite list must reach every element at a finite index.','List binary words by length, and then alphabetically within each length. Every finite word eventually appears.','Listing all a-only words before any b word would postpone b forever.',{kind:'enumeration',enumeration:'strings',parameter:10}),
t('Integers and rational numbers can be listed','Alternating positive and negative integers lists all of Z. Rational pairs can be traversed diagonally and reduced duplicates omitted.','The integer list 0,1,−1,2,−2,… reaches every integer; a rational listing must also include signs and zero.','An infinite row-by-row traversal of all pairs never reaches the second row.',{kind:'enumeration',enumeration:'rationals',parameter:12}),
t('Cantor’s diagonal escapes every proposed list','For a proposed list of infinite binary sequences, construct a sequence whose nth bit differs from the nth bit of row n. It differs from every listed row.','The visible diagonal illustrates finitely many positions; the argument defines the flipped bit for every natural n.','Finite binary words are countable; all infinite binary sequences form a different, uncountable set.',{kind:'diagonal',parameter:5}),
t('Equivalent definitions of countability','For a nonempty infinite set, a listing, a bijection with natural numbers and an injection into natural numbers give equivalent ways to establish countability. Finite and empty cases are handled separately.','Listing integer magnitudes with alternating signs assigns each integer a unique finite index.','A surjection from the empty set onto natural numbers cannot exist; check boundary cases when quoting equivalences.',{kind:'enumeration',enumeration:'integers',parameter:11}),
t('Countable unions and products remain countable','A countable family of countable sets can be traversed by diagonal index pairs; a finite product of countable sets is countable. This uses a fair schedule.','List pairs (i,j) by increasing i+j so each fixed pair appears after finitely many earlier pairs.','An infinite product is different: all infinite binary choices are uncountable.',{kind:'enumeration',enumeration:'pairs',parameter:14}),
t('Cantor’s theorem for power sets','For any function f:S→P(S), the diagonal set D={x∈S:x∉f(x)} differs from f(x) at x for every x. Therefore f is never onto.','If D=f(d), then d∈D exactly when d∉D, a contradiction.','The theorem applies to every set, not only real numbers or decimal expansions.',{kind:'diagonal',parameter:6}),
t('There are more languages than programs','Finite machine descriptions are countable, but languages over a nonempty finite alphabet form the power set of the countably infinite set Σ*, which is uncountable.','Each language chooses yes or no independently for every finite word; some such choices have no recognizing program.','Countably many words does not mean countably many subsets of words.',{kind:'diagonal',parameter:7}),
t('Use cardinality without overstating computability','An effective finite description gives only countably many describable objects. A countability argument proves that unrecognizable languages exist, but does not identify a particular one by itself.','Dovetailing enumerates finite programs; diagonal reasoning shows that this cannot cover every possible language.','Countable does not mean that every subset has an effective enumeration or a decision algorithm.',{kind:'enumeration',enumeration:'strings',parameter:15})
];

