// Definitions belong to the actual model used in each lesson, rather than a
// subject-wide CPU/variable glossary that silently assumes prior knowledge.
export const glossary={
 words:['Alphabet: The allowed finite set of input symbols.','Word: A finite ordered sequence of symbols.','ε: The unique word containing zero symbols; its length is zero.'],
 language:['Language: A set whose elements are whole words.','Membership: Whether a particular whole word is in a set.','Concatenation: Joining two words in their original order.'],
 dfa:['State: One of finitely many summaries of the consumed input.','Transition: The next-state rule for one current state and input symbol.','Accepting state: A state that accepts when the entire input has been consumed.'],
 nfa:['Active set: All states reachable after the same input prefix.','ε-closure: States reachable with no symbol consumption, including the starting states.','Acceptance: At least one full-input branch finishes in an accepting state.'],
 regex:['Union |: Choose a word from either operand language.','Concatenation: Choose a word from each operand and join in order.','Star *: Repeat an operand zero or more times.'],
 subset:['Subset state: A set of original NFA states stored as one DFA memory.','Reachable: Obtainable from the start by a finite input word.','Dead subset: The empty active set, from which no branch can continue.'],
 minimize:['Equivalent states: States with the same acceptance result for every appended suffix.','Partition: Disjoint blocks covering all relevant states.','Refinement: Splitting blocks when their future behaviors differ.'],
 grammar:['Terminal: An output symbol that is not rewritten.','Nonterminal: A named placeholder rewritten by productions.','Derivation: A sequence of permitted rewrites from the start symbol.'],
 'grammar-properties':['Nullable: Able to derive the empty word through zero or more permitted rewrites.','Generating: Able to derive some terminal-only word.','Reachable: Appearing in a derivation from the start symbol.'],
 'normal-form':['Production: A rule replacing one nonterminal by a sequence.','CNF: Rules with two nonterminals or one terminal on the right, with a stated start ε exception.','GNF: A terminal followed by zero or more nonterminals, with a stated start ε exception.'],
 pda:['Stack: Last-in-first-out storage, with the top removed first.','Obligation: One unit of unmatched input to be cancelled by later symbols.','Bottom marker Z: The sentinel below every unmatched item.'],
 palindrome:['Reversal: The same symbols read from last to first.','Midpoint: Where the machine switches from pushing to matching.','Nondeterministic choice: Several possible moves, with acceptance by one successful full run.'],
 tm:['Tape: Read-write cells extending as needed beyond the input.','Head: The position of the cell currently read or written.','Configuration: State, head position and tape contents together.'],
 pumping:['Pumping length p: The hypothetical finite bound supplied by regularity.','Decomposition xyz: A split with |xy|≤p and nonempty y.','Pumping exponent i: A nonnegative number of copies of y.'],
 nerode:['Prefix: The already consumed part of an input.','Distinguishing suffix: One shared continuation producing opposite membership results.','Equivalence class: Prefixes with identical acceptance behavior for every continuation.'],
 closure:['Universe Σ*: Every finite word over the specified alphabet.','Complement: Words in the universe that are outside a language.','Closure: Applying an operation to members of a family always stays in that family.'],
 hierarchy:['Regular: Recognizable with finitely many states.','Context-free: Generable by a CFG, equivalently recognizable by an NPDA.','Decidable: Having a correct yes/no algorithm that always halts.'],
 decision:['Encoding: A finite word representing an object unambiguously.','Decider: A correct yes/no procedure halting on every valid input.','Recognizer: Accepts all members but may run forever on nonmembers.'],
 reduction:['Reduction: An effective transformation preserving the answer of a source instance.','Semantic property: A property determined only by the recognized language.','Nontrivial property: True for at least one recognizable language and false for another.'],
 dovetail:['Branch: One ongoing simulation in a collection.','Fairness: Every unfinished branch receives more steps eventually.','Recognizer: A procedure that accepts members, possibly running forever otherwise.'],
 enumeration:['Enumeration: A listing that eventually reaches every element.','Countable: Finite or admitting a listing indexed by natural numbers.','Diagonal order: Visiting index pairs by increasing sum to avoid starving later rows.'],
 diagonal:['Infinite binary sequence: A bit at every natural-number position.','Diagonal bit: The entry at coordinate n in proposed row n of a list.','Uncountable: No natural-number-indexed listing covers the whole set.']
};
for(const kind of ['grammar','pda','nerode','pumping','tm','hierarchy'])glossary[kind].push('Repetition a^n: A sequence containing n copies of a; n is a nonnegative integer.');
glossary.pumping.push('Length |w|: The number of symbols in w; |xy|≤p bounds the combined length of x and y.');
glossary.grammar.push('Parser dot: Marks the next production symbol to match; symbols before it have already been matched.','Origin index: The input position where a chart-parser production began matching.');
topics[102].spec.variant='closure';
